{"tiddlers":{"$:/plugins/huwiki/graph-studio/styles":{"title":"$:/plugins/huwiki/graph-studio/styles","type":"text/css","tags":"$:/tags/Stylesheet","text":"/* Forge Graph Studio: style only; TW5-Graph and Vis-Network remain unmodified. */
.forge-graph-workbench{max-width:1320px;margin:0 auto;color:inherit}
.forge-graph-eyebrow{font:600 .8rem/1.4 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.1em;color:#297a78}
.forge-graph-lead{font-size:1.08rem;line-height:1.6;max-width:74ch}
.forge-graph-nav{display:flex;gap:.55rem;flex-wrap:wrap;margin:1rem 0}
.forge-graph-nav .tc-tiddlylink{display:inline-block;padding:.55rem .85rem;border:1px solid #b9d6d2;border-radius:999px;text-decoration:none;font-weight:600;background:#ecf6f3}
.forge-graph-nav .tc-tiddlylink:hover{background:#dcefeb}
.forge-graph-stage{width:100%;position:relative;margin:1rem 0 1.25rem;border:1px solid #c4ded9;border-radius:14px;overflow:hidden;background:#fffefa}
.forge-graph-stage .graph-canvas{min-height:520px;height:min(65vh,690px)!important;width:100%!important;border:none!important}
.forge-graph-stage .graph-engine-vis-network{min-height:520px;height:min(65vh,690px)!important}
.forge-graph-hints{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:12px;margin:1rem 0}
.forge-graph-hints>div{border:1px solid #d5e3df;background:#f5faf8;padding:1rem;border-radius:12px}
.forge-graph-hints strong{display:block;margin-bottom:.3rem}
@media(max-width:760px){.forge-graph-stage .graph-canvas,.forge-graph-stage .graph-engine-vis-network{height:58vh!important;min-height:340px}.forge-graph-nav .tc-tiddlylink{padding:.45rem .6rem}}


/* Contextual Forge editor: keep the native graph toolbar and canvas in view. */
.forge-graph-editor{
 display:none;position:absolute;top:58px;right:12px;z-index:20;
 width:min(328px,calc(100% - 24px));max-height:calc(100% - 72px);
 overflow-y:auto;background:#fffefa;color:#163d46;
 border:1px solid #bbd3d0;box-shadow:0 8px 22px rgba(21,56,62,.16);
 border-radius:8px;padding:10px;box-sizing:border-box
}
.forge-graph-editor.is-open{display:block}
.forge-graph-editor-heading{display:flex;align-items:center;justify-content:space-between;
 gap:12px;margin:0 0 7px;font:600 1rem/1.4 system-ui,sans-serif}
.forge-graph-editor-heading button.forge-graph-close{border:0;background:transparent;
 color:#536a6b;cursor:pointer;font:normal 1.5rem/1 system-ui,sans-serif;
 width:32px;height:32px;padding:2px;border-radius:6px}
.forge-graph-editor-heading button.forge-graph-close:hover,
.forge-graph-editor-heading button.forge-graph-close:focus-visible{background:#eaf2f1;color:#173d46}
.forge-graph-editor-panels{display:block}
.forge-graph-editor-panel{padding:0;margin:0;min-width:0}
.forge-graph-editor-panel[hidden]{display:none!important}
.forge-graph-field{display:flex;flex-direction:column;gap:.22rem;
 font:.84rem/1.35 system-ui,sans-serif;margin:.48rem 0}
.forge-graph-field input,.forge-graph-field select{box-sizing:border-box;min-width:0;
 width:100%;min-height:34px;font:inherit;padding:.38rem .45rem;
 border:1px solid #abbab8;border-radius:5px;background:#fff;color:#163d46}
.forge-graph-editor-panel button{font:600 .9rem/1.3 system-ui,sans-serif;
 min-height:36px;padding:.45rem .65rem;background:#163d46;color:white;
 border:0;border-radius:6px;cursor:pointer;margin-top:.35rem}
.forge-graph-editor-panel button:hover,.forge-graph-editor-panel button:focus-visible{background:#286979}
.forge-graph-feedback{font:.82rem/1.4 system-ui,sans-serif;color:#286979;
 margin:.55rem 0 0;min-height:0}
@media(max-width:600px){
 .forge-graph-editor{top:56px;right:5px;width:min(310px,calc(100% - 10px));
 max-height:calc(100% - 64px);padding:9px}
}

/* Optional local images and tiny SVG sketchpad in the existing popover. */
.forge-graph-image-tools{display:flex;flex-direction:column;gap:5px;margin:.35rem 0 .55rem}
.forge-graph-image-tools .forge-graph-field{margin:0}
.forge-graph-image-tools input[type=file]{font-size:.78rem;padding:.3rem .15rem;min-height:36px}
.forge-graph-image-tools button.forge-graph-draw-toggle{
 align-self:flex-start;background:transparent;color:#163d46;border:1px solid #a4c0bb;
 margin:.1rem 0 .3rem;font-weight:600
}
.forge-graph-image-tools button.forge-graph-draw-toggle:hover{background:#eaf2ef}
.forge-graph-drawing[hidden]{display:none!important}
.forge-graph-sketch{display:block;width:100%;height:auto;aspect-ratio:7/4;
 border:1px solid #b9d1ce;border-radius:5px;background:#fff;
 touch-action:none;cursor:crosshair;user-select:none}
.forge-graph-draw-actions{display:flex;gap:8px;justify-content:flex-end}
.forge-graph-draw-actions button{font-size:.83rem}
"},"Graph Studio · Om pluginet":{"title":"Graph Studio · Om pluginet","type":"text/vnd.tiddlywiki","text":"<$list filter="[{$:/language}prefix[$:/languages/da]]" variable="graphLocale">
Graph Studio er Forge-tilpasningen omkring [[TW5-Graph|https://flibbles.github.io/tw5-graph/]] og [[Vis-Network|https://github.com/flibbles/tw5-vis-network]]. De originale Flibbles-plugins følger med uændrede. Graph Studio tilbyder en genbrugelig stil og erklærer afhængighederne, så andre Forge Editions kan tilvælge hele værktøjet. Brug `<$graph.view $tiddler="$:/graph/Platon" />` til at vise en graf i en tiddler.
</$list>
<$list filter="[{$:/language}!prefix[$:/languages/da]]" variable="graphLocale">
Graph Studio is the Forge layer around [[TW5-Graph|https://flibbles.github.io/tw5-graph/]] and [[Vis-Network|https://github.com/flibbles/tw5-vis-network]]. Both upstream plugins are bundled unchanged. Graph Studio provides reusable presentation styles and dependency metadata. Embed any graph with `<$graph.view $tiddler="$:/graph/Platon" />`.
</$list>"},"$:/plugins/huwiki/graph-studio/widgets/editor.js":{"title":"$:/plugins/huwiki/graph-studio/widgets/editor.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/plugins/huwiki/graph-studio/widgets/editor.js
type: application/javascript
module-type: widget

Forge Graph Editor: accessible direct controls on top of unmodified TW5-Graph.
No remote dependencies, no additional graph renderer, no background saves.
\*/
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;
var SHAPES = ["box","ellipse","circle","dot","diamond","hexagon","square","star","triangle","triangleDown","database","text","image"];
var FIELDS = ["forbinder","fører-til","forudsætter","symboliserer"];
// Transient form state survives TiddlyWiki widget refreshes and graph redraws.
var editorStateByGraph = Object.create(null);
var LABELS = {
 da: {node:"Tilføj node",newName:"Nodens titel",create:"Opret / tilføj",edge:"Forbind noder",from:"Fra",to:"Til",relation:"Relation",connect:"Opret forbindelse",
  style:"Udseende",selected:"Vælg node",shape:"Form",color:"Farve",size:"Størrelse",icon:"Billede (valgfrit)",apply:"Gem udseende",upload:"Upload billede",draw:"Tegn selv",clear:"Ryd",useDrawing:"Brug tegning",
  imageReady:"Billedet er klar. Vælg Gem udseende.",largeImage:"Billedet er for stort (maks. 5 MB).",invalidImage:"Vælg PNG, JPEG, GIF, WebP eller en enkel SVG uden aktive elementer.",readError:"Billedet kunne ikke læses.",emptyDrawing:"Tegn først noget med mus eller finger.",drawingTitle:"Min graftegning",
  intro:"Dette værksted ændrer rigtige TiddlyWiki-tiddlere. Du kan fortsat trække noder rundt på kortet.",
  nameRequired:"Skriv et navn på noden.",unsafe:"Systemtiddlere kan ikke ændres her.",nodeCreated:"Node tilføjet: ",nodeExisting:"Eksisterende tiddler føjet til grafen: ",
  edgeAdded:"Forbindelse oprettet.",edgeExists:"Forbindelsen findes allerede.",pickNodes:"Vælg to noder først.",
  styleSaved:"Udseende opdateret.",needIcon:"Vælg et billede, når formen er Billede.",notFound:"Noden findes ikke.",
  none:"Intet billede",image:"Billede",directions:"Tilføj node direkte her. Forbindelser oprettes ved at vælge Fra og Til – uden træk-bevægelser.",
  textLabels:["forbinder","fører til","forudsætter","symboliserer"]},
 en: {node:"Add node",newName:"Node title",create:"Create / add",edge:"Connect nodes",from:"From",to:"To",relation:"Relationship",connect:"Create connection",
  style:"Appearance",selected:"Select node",shape:"Shape",color:"Color",size:"Size",icon:"Image (optional)",apply:"Save appearance",upload:"Upload image",draw:"Draw",clear:"Clear",useDrawing:"Use drawing",
  imageReady:"Image ready. Choose Save appearance.",largeImage:"Image is too large (5 MB maximum).",invalidImage:"Choose PNG, JPEG, GIF, WebP, or a simple SVG without active content.",readError:"Could not read this image.",emptyDrawing:"Draw something using mouse or touch first.",drawingTitle:"My graph drawing",
  intro:"This editor changes ordinary TiddlyWiki tiddlers. You can still drag nodes around the graph.",
  nameRequired:"Enter a node title.",unsafe:"System tiddlers cannot be changed here.",nodeCreated:"Node added: ",nodeExisting:"Existing tiddler added to the graph: ",
  edgeAdded:"Connection created.",edgeExists:"Connection already exists.",pickNodes:"Select both nodes first.",
  styleSaved:"Appearance updated.",needIcon:"Select an image for the Image shape.",notFound:"Node was not found.",
  none:"No image",image:"Image",directions:"Add nodes directly here. Connect nodes by selecting From and To – no drag gesture required.",
  textLabels:["connects","leads to","requires","symbolizes"]}
};

var ForgeGraphEditor = function(parseTreeNode,options) {
 this.initialise(parseTreeNode,options);
};
ForgeGraphEditor.prototype = new Widget();

ForgeGraphEditor.prototype.execute = function() {
 this.graphTitle = this.getAttribute("graph","");
 this.state = editorStateByGraph[this.graphTitle] || (editorStateByGraph[this.graphTitle] = {});
 this.graphTiddler = this.wiki.getTiddler(this.graphTitle);
 this.graphTag = this.graphTiddler && this.graphTiddler.fields["forge-node-tag"];
 this.language = (this.wiki.getTiddlerText("$:/language","")||"").indexOf("/da") >= 0 ? "da" : "en";
 this.labels = LABELS[this.language];
 this.makeChildWidgets();
};

ForgeGraphEditor.prototype.nodes = function() {
 if(!this.graphTiddler) return [];
 var filter = this.graphTiddler.fields.filter || "";
 var results = this.wiki.filterTiddlers(filter);
 return results.filter(function(title) {
  return !!this.wiki.getTiddler(title) && title.indexOf("$:/") !== 0;
 },this).sort(function(a,b){return a.localeCompare(b);});
};

ForgeGraphEditor.prototype.render = function(parent,nextSibling) {
 this.parentDomNode = parent;
 this.computeAttributes();
 this.execute();
 var doc = this.document;
 var root = doc.createElement("section");
 root.className = "forge-graph-editor" + (this.state.mode?" is-open":"");
 root.addEventListener("forge-graph-action",function(event){
  var details=event.detail || {}, mode=details.mode;
  if(["node","edge","style"].indexOf(mode)<0)return;
  if(mode==="style"){
   var selected=details.node;
   if(!selected || self.nodes().indexOf(selected)<0)return;
   if(self.state.selectedNode!==selected)self.state.draft=null;
   self.state.selectedNode=selected;
  }
  self.state.mode=(mode!=="style" && self.state.mode===mode)?"":mode;
  self.refreshSelf();
 });
 root.setAttribute("aria-label",this.language === "da" ? "Grafværksted" : "Graph editor");
 parent.insertBefore(root,nextSibling);
 this.domNodes = [root];
 var L = this.labels;
 var self = this;
 function el(parent,tag,cls,textValue) {
  var n=doc.createElement(tag);
  if(cls)n.className=cls;
  if(textValue!==undefined)n.textContent=textValue;
  parent.appendChild(n);
  return n;
 }
 function labelInput(container,labelText,input,cls){
  var label=el(container,"label","forge-graph-field");
  el(label,"span","",labelText);
  if(cls)input.className=cls;
  label.appendChild(input);
  return input;
 }
 function input(type,cls,value){
  var e=doc.createElement("input");e.type=type;if(cls)e.className=cls;
  if(value!==undefined)e.value=value;return e;
 }
 function selector(cls,options,selected){
  var e=doc.createElement("select");e.className=cls;
  options.forEach(function(o){
   var opt=doc.createElement("option");
   opt.value=String(o.value);opt.textContent=o.label;e.appendChild(opt);
  });
  if(selected!==undefined)e.value=selected;
  return e;
 }
 function doButton(parent,cls,title,fn) {
  var b=el(parent,"button",cls,title);b.type="button";
  b.addEventListener("click",function(event){event.preventDefault();event.stopPropagation();fn();});
  return b;
 }
 function notice(textValue) {
  self.message=textValue;
  output.textContent=textValue;
 }
 if(!this.graphTiddler || !this.graphTag){
  el(root,"p","forge-graph-editor-warning",this.language==="da"?"Grafen har ingen redigerbart Forge-tag.":"This graph does not specify an editable Forge tag.");
  return;
 }
 var heading=el(root,"div","forge-graph-editor-heading");
 el(heading,"strong","forge-graph-editor-title",this.state.mode==="node"?L.node:this.state.mode==="edge"?L.edge:L.style);
 var close=doButton(heading,"forge-graph-close","×",function(){self.state.mode="";self.refreshSelf();});
 close.setAttribute("aria-label",this.language==="da"?"Luk redigering":"Close editor");
 var panels=el(root,"div","forge-graph-editor-panels");
 var nodePanel=el(panels,"div","forge-graph-editor-panel");
 nodePanel.hidden=this.state.mode!=="node";
 var name=labelInput(nodePanel,L.newName,input("text","forge-graph-node-name",this.state.pendingName||""),"forge-graph-node-name");
 name.autocomplete="off";name.maxLength=120;
 name.addEventListener("input",function(){self.state.pendingName=name.value;});
 doButton(nodePanel,"forge-graph-create-node",L.create,function(){
  var title=name.value.trim();
  if(!title){notice(L.nameRequired);name.focus();return;}
  if(title.indexOf("$:/")===0){notice(L.unsafe);return;}
  var t=self.wiki.getTiddler(title);
  if(t){
   var tags=t.getFieldList("tags");
   if(tags.indexOf(self.graphTag)<0)self.wiki.addTiddler(new $tw.Tiddler(t,{tags:tags.concat([self.graphTag])}));
   notice(L.nodeExisting+title);
  }else{
   self.wiki.addTiddler(new $tw.Tiddler({title:title,text:"",tags:[self.graphTag],color:"#397f8d","graph-shape":"box","graph-size":"25"}));
   notice(L.nodeCreated+title);
  }
  self.state.pendingName="";
  self.state.selectedNode=title;
  self.state.edgeTo=title;
  self.state.draft=null;
  self.state.mode="";
  self.refreshSelf();
 });
 var nodes=this.nodes();
 var nodeOptions=nodes.map(function(title){return {value:title,label:title};});
 var edgePanel=el(panels,"div","forge-graph-editor-panel");
 edgePanel.hidden=this.state.mode!=="edge";
 var from=labelInput(edgePanel,L.from,selector("forge-graph-edge-from",nodeOptions,this.state.edgeFrom||nodes[0]||""));
 var to=labelInput(edgePanel,L.to,selector("forge-graph-edge-to",nodeOptions,this.state.edgeTo||nodes[1]||nodes[0]||""));
 var relationOptions=FIELDS.map(function(field,i){return {value:field,label:L.textLabels[i]};});
 var edgeType=labelInput(edgePanel,L.relation,selector("forge-graph-edge-type",relationOptions,this.state.edgeType||"forbinder"));
 from.addEventListener("change",function(){self.state.edgeFrom=from.value;});
 to.addEventListener("change",function(){self.state.edgeTo=to.value;});
 edgeType.addEventListener("change",function(){self.state.edgeType=edgeType.value;});
 doButton(edgePanel,"forge-graph-add-edge",L.connect,function(){
  var fromTitle=from.value,toTitle=to.value,field=edgeType.value;
  if(!fromTitle||!toTitle||FIELDS.indexOf(field)<0){notice(L.pickNodes);return;}
  var source=self.wiki.getTiddler(fromTitle),target=self.wiki.getTiddler(toTitle);
  if(!source||!target||self.nodes().indexOf(fromTitle)<0||self.nodes().indexOf(toTitle)<0){notice(L.notFound);return;}
  var links=source.getFieldList(field);
  if(links.indexOf(toTitle)>=0){notice(L.edgeExists);return;}
  self.wiki.addTiddler(new $tw.Tiddler(source,((function(){var patch={};patch[field]=$tw.utils.stringifyList(links.concat([toTitle]));return patch;})())));
  notice(L.edgeAdded);
  self.state.mode="";
  self.refreshSelf();
 });
 var stylePanel=el(panels,"div","forge-graph-editor-panel");
 stylePanel.hidden=this.state.mode!=="style";
 if(nodes.indexOf(this.state.selectedNode)<0)this.state.selectedNode=nodes[0]||"";
 var current=this.wiki.getTiddler(this.state.selectedNode);
 var draft=this.state.draft && this.state.draft.node===this.state.selectedNode ? this.state.draft:null;
 var pick=labelInput(stylePanel,L.selected,selector("forge-graph-style-node",nodeOptions,this.state.selectedNode));
 pick.addEventListener("change",function(){self.state.selectedNode=pick.value;self.state.draft=null;self.refreshSelf();});
 current=this.wiki.getTiddler(this.state.selectedNode);
 var shape=labelInput(stylePanel,L.shape,selector("forge-graph-style-shape",SHAPES.map(function(s){return {value:s,label:s==="image"?L.image:s};}),draft ? draft.shape : current&&current.fields["graph-shape"]||"box"));
 var color=labelInput(stylePanel,L.color,input("color","forge-graph-style-color",draft ? draft.color : current&&/^#[0-9a-fA-F]{6}$/.test(current.fields.color||"")?current.fields.color:"#397f8d"));
 var size=labelInput(stylePanel,L.size,input("number","forge-graph-style-size",draft ? draft.size : current&&current.fields["graph-size"]||"25"));
 size.min="12";size.max="80";size.step="1";
 var iconTitles=this.wiki.filterTiddlers("[all[shadows+tiddlers]tag[GraphStudio/Icon]]");
 // Ordinary TiddlyWiki image tiddlers include uploaded artwork and SVG
 // exported from a drawing app. Keep bundled examples alongside them.
 this.wiki.each(function(tiddler,title){
  if(title.indexOf("$:/")!==0 &&
     /^image\/(png|jpeg|gif|webp|svg\+xml)$/i.test(tiddler.fields.type||"") &&
     iconTitles.indexOf(title)<0)iconTitles.push(title);
 });
 iconTitles.sort(function(a,b){return a.localeCompare(b);});
 var iconOptions=[{value:"",label:L.none}].concat(iconTitles.map(function(title){return {value:title,label:title.replace("GraphStudio/","")};}));
 var icon=labelInput(stylePanel,L.icon,selector("forge-graph-style-icon",iconOptions,draft ? draft.icon : current&&current.fields.icon||""));
 function rememberDraft(){
  self.state.draft={node:pick.value,shape:shape.value,color:color.value,size:size.value,icon:icon.value};
 }
 [shape,color,size,icon].forEach(function(control){
  control.addEventListener("input",rememberDraft);
  control.addEventListener("change",rememberDraft);
 });
 icon.addEventListener("change",function(){
  if(icon.value){shape.value="image";rememberDraft();}
 });
 // Store image files as normal image tiddlers: never external URLs, so
 // a downloaded single-file wiki retains the artwork when opened offline.
 function freshImageTitle(base){
  base=String(base||L.image).replace(/[\[\]<>]/g," ").trim().slice(0,70)||L.image;
  var candidate=base,n=2;
  while(self.wiki.tiddlerExists(candidate)||self.wiki.isShadowTiddler(candidate)){
   candidate=base+" ("+(n++)+")";
  }
  return candidate;
 }
 function chooseImage(title){
  if(!Array.prototype.some.call(icon.options,function(option){return option.value===title;})){
   var option=doc.createElement("option");
   option.value=title;option.textContent=title;icon.appendChild(option);
  }
  icon.value=title;
  shape.value="image";
  rememberDraft();
 }
 var imageTools=el(stylePanel,"div","forge-graph-image-tools");
 var upload=doc.createElement("input");
 upload.type="file";upload.className="forge-graph-upload-image";
 upload.accept="image/png,image/jpeg,image/gif,image/webp,image/svg+xml,.svg";
 labelInput(imageTools,L.upload,upload);
 upload.addEventListener("change",function(){
  var file=upload.files && upload.files[0];
  if(!file)return;
  if(file.size>5*1024*1024){notice(L.largeImage);upload.value="";return;}
  var type=file.type.toLowerCase() || (/\.svg$/i.test(file.name)?"image/svg+xml":"");
  if(!/^image\/(png|jpeg|gif|webp|svg\+xml)$/.test(type)){
   notice(L.invalidImage);upload.value="";return;
  }
  var reader=new FileReader();
  reader.onerror=function(){notice(L.readError);upload.value="";};
  reader.onload=function(){
   var content=String(reader.result||"");
   if(type==="image/svg+xml"){
    if(!/<svg(?:\s|>)/i.test(content) ||
      /<(?:script|foreignObject|iframe|style)\b|<!DOCTYPE|<!ENTITY|\bon[a-z]+\s*=|\b(?:href|xlink:href)\s*=|javascript:|\burl\s*\(/i.test(content)){
      notice(L.invalidImage);upload.value="";return;
    }
   }else{
    var comma=content.indexOf(",");
    if(comma<0){notice(L.readError);upload.value="";return;}
    content=content.slice(comma+1);
   }
   var title=freshImageTitle(file.name.replace(/\.[^.]+$/,""));
   chooseImage(title);
   self.wiki.addTiddler(new $tw.Tiddler({
    title:title,type:type,tags:["GraphStudio/Image"],text:content
   }));
   self.message=L.imageReady;
   self.refreshSelf();
  };
  if(type==="image/svg+xml")reader.readAsText(file);
  else reader.readAsDataURL(file);
 });
 // A tiny optional SVG drawing surface; not a second editor, canvas engine,
 // plugin dependency or persistent toolbar.
 var drawButton=doButton(imageTools,"forge-graph-draw-toggle",L.draw,function(){
  self.state.drawOpen=!self.state.drawOpen;
  drawingBox.hidden=!self.state.drawOpen;
 });
 drawButton.setAttribute("aria-expanded",this.state.drawOpen?"true":"false");
 var drawingBox=el(stylePanel,"div","forge-graph-drawing");
 drawingBox.hidden=!this.state.drawOpen;
 var sketch=doc.createElementNS("http://www.w3.org/2000/svg","svg");
 sketch.setAttribute("viewBox","0 0 280 160");
 sketch.setAttribute("role","img");
 sketch.setAttribute("aria-label",this.language==="da"?"Tegnefelt":"Drawing area");
 sketch.classList.add("forge-graph-sketch");
 drawingBox.appendChild(sketch);
 var strokes=this.state.sketchPaths || (this.state.sketchPaths=[]);
 function strokePath(points){
  return points.map(function(p,i){return (i?"L":"M")+p[0]+" "+p[1];}).join(" ") +
   (points.length===1?" l0.1 0.1":"");
 }
 function renderSketch(){
  while(sketch.firstChild)sketch.removeChild(sketch.firstChild);
  strokes.forEach(function(points){
   var path=doc.createElementNS("http://www.w3.org/2000/svg","path");
   path.setAttribute("d",strokePath(points));
   path.setAttribute("fill","none");
   path.setAttribute("stroke",color.value);
   path.setAttribute("stroke-width","3.5");
   path.setAttribute("stroke-linecap","round");
   path.setAttribute("stroke-linejoin","round");
   sketch.appendChild(path);
  });
 }
 function sketchPoint(event){
  var rect=sketch.getBoundingClientRect();
  var x=Math.max(0,Math.min(280,((event.clientX-rect.left)/Math.max(rect.width,1))*280));
  var y=Math.max(0,Math.min(160,((event.clientY-rect.top)/Math.max(rect.height,1))*160));
  return [Math.round(x*10)/10,Math.round(y*10)/10];
 }
 var activeStroke=null;
 sketch.addEventListener("pointerdown",function(event){
  if(event.button!==0 && event.pointerType==="mouse")return;
  event.preventDefault();
  activeStroke=[sketchPoint(event)];
  strokes.push(activeStroke);
  if(sketch.setPointerCapture){
   try{sketch.setPointerCapture(event.pointerId);}catch(e){}
  }
  renderSketch();
 });
 sketch.addEventListener("pointermove",function(event){
  if(!activeStroke)return;
  event.preventDefault();
  activeStroke.push(sketchPoint(event));
  renderSketch();
 });
 function endStroke(event){activeStroke=null;}
 sketch.addEventListener("pointerup",endStroke);
 sketch.addEventListener("pointercancel",endStroke);
 renderSketch();
 var drawingButtons=el(drawingBox,"div","forge-graph-draw-actions");
 doButton(drawingButtons,"forge-graph-draw-clear",L.clear,function(){
  self.state.sketchPaths=[];strokes=self.state.sketchPaths;
  activeStroke=null;renderSketch();
 });
 doButton(drawingButtons,"forge-graph-draw-save",L.useDrawing,function(){
  if(!strokes.length){notice(L.emptyDrawing);return;}
  var paths=strokes.map(function(points){
   return '<path d="'+strokePath(points)+'"/>';
  }).join("");
  var svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 160">'+
    '<g fill="none" stroke="'+color.value+
    '" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">'+
    paths+'</g></svg>';
  var title=freshImageTitle(L.drawingTitle);
  chooseImage(title);
  self.state.sketchPaths=[];
  self.state.drawOpen=false;
  self.wiki.addTiddler(new $tw.Tiddler({
   title:title,type:"image/svg+xml",tags:["GraphStudio/Image"],text:svg
  }));
  self.message=L.imageReady;
  self.refreshSelf();
 });
 doButton(stylePanel,"forge-graph-apply-style",L.apply,function(){
  var title=pick.value,t=self.wiki.getTiddler(title);
  if(!t){notice(L.notFound);return;}
  var saved=self.state.draft && self.state.draft.node===title ? self.state.draft :
   {node:title,shape:shape.value,color:color.value,size:size.value,icon:icon.value};
  if(saved.shape==="image"&&!saved.icon){notice(L.needIcon);return;}
  var num=Math.max(12,Math.min(80,Number(saved.size)||25));
  var changes={"graph-shape":saved.shape,"graph-size":String(Math.round(num)),color:saved.color,icon:saved.shape==="image"?saved.icon:""};
  self.state.draft=null;
  self.state.selectedNode=title;
  self.wiki.addTiddler(new $tw.Tiddler(t,changes));
  notice(L.styleSaved);
  self.state.mode="";
  self.refreshSelf();
 });
 var output=el(root,"p","forge-graph-feedback",this.message||"");
 output.setAttribute("role","status");output.setAttribute("aria-live","polite");
};

ForgeGraphEditor.prototype.refresh=function(changedTiddlers){
 var attributes=this.computeAttributes();
 if($tw.utils.count(attributes))return this.refreshSelf();
 if(changedTiddlers["$:/language"]||changedTiddlers[this.graphTitle])return this.refreshSelf();
 var names=this.nodes();
 for(var title in changedTiddlers){
  var t=this.wiki.getTiddler(title);
  if(names.indexOf(title)>=0||(t&&t.hasTag&&t.hasTag(this.graphTag)))return this.refreshSelf();
 }
 return false;
};
exports["forge-graph-editor"]=ForgeGraphEditor;
