"use strict";
exports.name="forgeGraphControls";
exports.init=function(network){
 var surface=this.element;
 if(!surface || !surface.closest || !surface.closest(".forge-graph-stage"))return;
 function notify(mode,node){
  var stage=surface.closest(".forge-graph-stage");
  var editor=stage && stage.querySelector(".forge-graph-editor");
  if(!editor)return;
  var doc=surface.ownerDocument;
  var event=doc.createEvent("CustomEvent");
  event.initCustomEvent("forge-graph-action",false,false,{mode:mode,node:node});
  editor.dispatchEvent(event);
 }
 // Capture the familiar upstream buttons, opening exactly one small panel.
 // Stop the Vis two-step gesture so the button cannot appear ineffective.
 // Vis-Network handles these buttons on pointer-down, replacing the DOM
 // before a native click is fired. Intercept the pointer *before* its handler.
 function onToolbarAction(event){
  var origin=event.target && (event.target.nodeType===1?event.target:event.target.parentElement);
  var button=origin && origin.closest && origin.closest(".vis-button");
  if(!button || !surface.contains(button))return;
  var mode=button.classList.contains("vis-add")?"node":button.classList.contains("vis-connect")?"edge":null;
  if(!mode)return;
  event.preventDefault();
  event.stopImmediatePropagation();
  // A mouse/touch click following pointerdown must not toggle the panel back off.
  // A synthetic keyboard click (detail 0) still opens the relevant panel.
  if(event.type==="pointerdown" || (event.type==="click"&&event.detail===0))notify(mode);
 }
 surface.addEventListener("pointerdown",onToolbarAction,true);
 surface.addEventListener("click",onToolbarAction,true);
 // Single click on a node opens its appearance panel without double-clicking.
 network.on("click",function(params){
  if(params.nodes && params.nodes.length)notify("style",params.nodes[0]);
 });
};
